package akogen.fabric.v6;
import java.util.*;import java.util.concurrent.*;import java.io.*;import com.google.gson.*;
/** Automatic appearance sharing. Public beta relay receives only opaque channels and cosmetic IDs. */
public final class CosmeticSync {
 static final int MAX_PEERS=32;static String catalog="";static final String EPOCH=UUID.randomUUID().toString().replace("-","");static boolean started,enabled=true;static long nextTick;static Object lastWorld;static String lastStatus="";static volatile Snapshot snapshot=Snapshot.EMPTY;
 static final BlockingQueue<Envelope> incoming=new ArrayBlockingQueue<Envelope>(128);static final Map<UUID,Remote> remotes=new LinkedHashMap<UUID,Remote>();static final Map<UUID,Object> visible=new LinkedHashMap<UUID,Object>();static final Map<Integer,Remote> byEntity=new HashMap<Integer,Remote>();
 static final class Config {boolean enabled=true;String host="broker.emqx.io";int port=8883;}
 static Config config=new Config();
 static final class Snapshot {static final Snapshot EMPTY=new Snapshot(null,new int[0],Collections.<String,UUID>emptyMap());final String own;final int[] ids;final Map<String,UUID> topics;Snapshot(String own,int[] ids,Map<String,UUID> topics){this.own=own;this.ids=ids;this.topics=Collections.unmodifiableMap(topics);}}
 static final class Envelope {String topic;byte[] body;Envelope(String topic,byte[] body){this.topic=topic;this.body=body;}}
 public static final class Remote {public UUID uuid;public Object entity;public Map<String,Assets.Entry> equipped=new LinkedHashMap<String,Assets.Entry>();String epoch;int[] ids=new int[0];long seen;public double phaseOffset;}
 static void status(String value){if(value.equals(lastStatus))return;lastStatus=value;Session.log("SYNC: "+value);}
 public static void start(){if(started)return;started=true;try{File file=new File(new File(Session.logPath).getParentFile(),"cosmetic-sync.json");Gson gson=new GsonBuilder().setPrettyPrinting().create();if(file.isFile()){try(Reader reader=new InputStreamReader(new FileInputStream(file),"UTF-8")){Config loaded=gson.fromJson(reader,Config.class);if(loaded!=null)config=loaded;}}else{try(Writer writer=new OutputStreamWriter(new FileOutputStream(file),"UTF-8")){writer.write(gson.toJson(config));}}if(config.host==null||!config.host.matches("[a-zA-Z0-9.-]{1,253}")||config.port<1||config.port>65535)throw new IOException("Invalid cosmetic relay configuration");enabled=config.enabled;if(!enabled){status("disabled by configuration");return;}Thread thread=new Thread(()->worker(),"Akogen-Cosmetic-Relay");thread.setDaemon(true);thread.start();status("automatic sharing ready");}catch(Throwable error){enabled=false;Session.error(error);}}
 static void worker(){int failures=0;while(Session.active&&enabled){MqttLink link=null;String published=null;try{if(snapshot.own==null){Thread.sleep(500);continue;}link=new MqttLink(config.host,config.port,(topic,body)->{Snapshot now=snapshot;if(now.topics.containsKey(topic))incoming.offer(new Envelope(topic,body));});link.open();status("connected to shared beta relay");failures=0;long lastPublish=0,lastPing=0;int[] lastIds=null;while(Session.active&&enabled){Snapshot state=snapshot;link.subscriptions(state.topics.keySet());long now=System.currentTimeMillis();if(published!=null&&!published.equals(state.own)){link.publish(published,SyncCodec.encode(catalog,EPOCH,new int[0],Session.time(),true));published=null;lastIds=null;}if(state.own!=null&&(now-lastPublish>=5000||!Arrays.equals(state.ids,lastIds))){link.publish(state.own,SyncCodec.encode(catalog,EPOCH,state.ids,Session.time(),false));published=state.own;lastIds=state.ids.clone();lastPublish=now;}if(now-lastPing>15000){link.ping();lastPing=now;}link.poll();}}catch(Throwable failure){if(Session.active){status("reconnecting ("+failure.getClass().getSimpleName()+")");try{Thread.sleep(Math.min(15000,1000L<<Math.min(4,failures++)));}catch(InterruptedException ignored){return;}}}finally{if(link!=null){if(published!=null)try{link.publish(published,SyncCodec.encode(catalog,EPOCH,new int[0],Session.time(),true));}catch(Exception ignored){}link.close();}}}}
 public static void tick()throws Exception{if(!enabled)return;long now=System.currentTimeMillis();if(now<nextTick)return;nextTick=now+500;Object level=Names.field(Session.mc,"level"),local=Names.field(Session.mc,"player");if(level!=lastWorld){remotes.clear();visible.clear();byEntity.clear();incoming.clear();lastWorld=level;}if(local==null||level==null){snapshot=Snapshot.EMPTY;return;}UUID own=(UUID)Names.call(local,"getUUID");double x=World.num(Names.call(local,"getX")),y=World.num(Names.call(local,"getY")),z=World.num(Names.call(local,"getZ"));List<Object> candidates=new ArrayList<Object>();final Map<Object,Double> distances=new IdentityHashMap<Object,Double>();for(Object player:(Iterable<?>)Names.call(level,"method_18456")){UUID id=(UUID)Names.call(player,"getUUID");if(id.equals(own))continue;try{if(Boolean.TRUE.equals(Names.call(player,"isInvisibleTo",local))||Boolean.TRUE.equals(Names.call(player,"isSpectator")))continue;}catch(Exception ignored){}double dx=World.num(Names.call(player,"getX"))-x,dy=World.num(Names.call(player,"getY"))-y,dz=World.num(Names.call(player,"getZ"))-z;double distance=dx*dx+dy*dy+dz*dz;if(distance<=48*48){candidates.add(player);distances.put(player,distance);}}Collections.sort(candidates,(a,b)->Double.compare(distances.get(a),distances.get(b)));visible.clear();Map<String,UUID> topics=new LinkedHashMap<String,UUID>();for(Object player:candidates){if(topics.size()>=MAX_PEERS)break;UUID id=(UUID)Names.call(player,"getUUID");visible.put(id,player);topics.put(SyncCodec.topic(id),id);}int[] localIds=new int[Session.equipped.size()];int at=0;for(Assets.Entry e:Session.equipped.values())localIds[at++]=e.id;snapshot=new Snapshot(SyncCodec.topic(own),localIds,topics);
  Envelope packet;int processed=0;while(processed++<64&&(packet=incoming.poll())!=null){UUID id=topics.get(packet.topic);if(id==null)continue;try{accept(id,SyncCodec.decode(packet.body,catalog),now);}catch(Exception ignored){}}
  Iterator<Map.Entry<UUID,Remote>> iterator=remotes.entrySet().iterator();byEntity.clear();while(iterator.hasNext()){Remote remote=iterator.next().getValue();remote.entity=visible.get(remote.uuid);if(remote.entity==null||now-remote.seen>18000){iterator.remove();continue;}byEntity.put(((Number)Names.call(remote.entity,"getId")).intValue(),remote);Assets.Entry cape=remote.equipped.get("cloak");if(cape!=null){CapeBridge.texture(cape,false);CapeBridge.texture(cape,true);}}
 }
 static void accept(UUID uuid,SyncCodec.State state,long now)throws Exception{Remote remote=remotes.get(uuid);if(state.clear){if(remote!=null&&state.epoch.equals(remote.epoch))remotes.remove(uuid);return;}Map<Integer,Assets.Entry> available=new HashMap<Integer,Assets.Entry>();for(Assets.Entry entry:Assets.entries)available.put(entry.id,entry);int flyers=0;Set<String> slots=new HashSet<String>();for(int id:state.ids){Assets.Entry e=available.get(id);if(e==null)throw new IOException("Unknown cosmetic");if(e.slot.equals("flying")){if(++flyers>2)throw new IOException("Too many flying pets");}else if(!slots.add(e.slot))throw new IOException("Duplicate cosmetic slot");}if(remote==null){remote=new Remote();remote.uuid=uuid;remotes.put(uuid,remote);}remote.entity=visible.get(uuid);if(!Arrays.equals(remote.ids,state.ids)||!state.epoch.equals(remote.epoch)){Map<String,Assets.Entry> next=new LinkedHashMap<String,Assets.Entry>();int index=0;for(int id:state.ids){Assets.Entry template=available.get(id);Assets.prepare(template);Assets.Entry e=null;for(Assets.Entry old:remote.equipped.values())if(old.id==id){e=old;break;}if(e==null){e=new Assets.Entry();e.id=template.id;e.name=template.name;e.group=template.group;e.file=template.file;e.slot=template.slot;e.config=template.config;e.model=template.model;e.texture=template.texture;e.layer=template.layer;}next.put(e.slot.equals("flying")?"flying:"+(index++):e.slot,e);}remote.equipped=next;remote.ids=state.ids.clone();}remote.epoch=state.epoch;remote.seen=now;double measured=state.phase-Session.time();remote.phaseOffset=measured;}
 static final Collection<Remote> renderPeers=Collections.unmodifiableCollection(remotes.values());
 public static Collection<Remote> players(){return renderPeers;}
 public static Map<String,Assets.Entry> selectionForEntity(int entityId)throws Exception{if(!Visibility.local())return Collections.<String,Assets.Entry>emptyMap();Object player=Names.field(Session.mc,"player");if(player!=null&&((Number)Names.call(player,"getId")).intValue()==entityId)return Session.equipped;Remote remote=Visibility.others()?byEntity.get(entityId):null;return remote==null?Collections.<String,Assets.Entry>emptyMap():remote.equipped;}
}
